insert into public.collections (slug, name, jp, group_type, accent_a, accent_b, motif, tagline, blurb, sort_order, featured, sub_fandoms, is_published) values
  ('jujutsu-kaisen', 'Jujutsu Kaisen', '呪術廻戦', 'anime', '#4B2BFF', '#A78BFF', 'smoke', 'Cursed static, pressed in ink.', 'Violet smoke, paper talismans and type that crackles like a bad signal. Original prints for fans who read every panel twice.', 1, true, '{}'::text[], true),
  ('attack-on-titan', 'Attack on Titan', '進撃の巨人', 'anime', '#A39780', '#C8102E', 'walls', 'Everything past the wall.', 'Stone grey, blood red and wind-torn cloth. Heavy, quiet designs built from rings of wall and a red horizon.', 2, true, '{}'::text[], true),
  ('demon-slayer', 'Demon Slayer', '鬼滅の刃', 'anime', '#FF6A13', '#12A5A0', 'flames', 'Flame on one side, tide on the other.', 'Brush-stroke fire meets brush-stroke water. Prints, props and katanas for the fan who picks a side and then wears both.', 3, true, '{}'::text[], true),
  ('one-piece', 'One Piece', 'ワンピース', 'anime', '#1C6FE0', '#F2C230', 'waves', 'Sea blue, sun yellow, no map.', 'Rolling waves, compass roses and sun-bleached colour. Original designs for long voyages and longer fest days.', 4, true, '{}'::text[], true),
  ('naruto', 'Naruto', 'ナルト', 'anime', '#FF7A00', '#1B2A4A', 'spiral', 'Orange hour, spiral wind.', 'Loud orange on night navy, with spirals and scattered leaves. Original prints for the fan who never gave up on the arc.', 5, true, '{}'::text[], true),
  ('beyond-anime', 'Beyond Anime', 'その先へ', 'beyond', '#FFB8DE', '#F4EFE6', 'ribbons', 'One more door, every other fandom.', 'Book quotes, stadium-tour sparkle, wizard-school candlelight, K-pop encores, pit-lane speed and animated-film warmth. Original designs, one door.', 6, true, array['Bookish', 'Jane Austen', 'Swiftie', 'Harry Potter', 'K-pop', 'F1', 'Pixar']::text[], true)
insert into public.products (id, slug, name, type, collection, tags, design_title, jp_title, description, images, variants, sizes, price_from, price_on_request, bundle_rule_id, customizable, featured, drop_of_week, stock, color_block, sort_order, is_published, created_at, updated_at) values
  ('p-cursed-static-oversized-t-shirt', 'cursed-static-oversized-t-shirt', 'Cursed Static Oversized T-Shirt', 'tshirt', 'jujutsu-kaisen', array['oversized', 'apparel', 'jjk', 'drop']::text[], 'Cursed Static', '呪いのノイズ', 'A back print of violet smoke breaking into scan-line static, with the title stacked in tall condensed caps. Printed on a black oversized drop-shoulder tee: back print up to 12×15 in, front hit up to 4×4 in. ₹800. Sizes XS–XXL — ask us on WhatsApp for the size chart before you order.', '[{"src":"/mockups/cursed-static-oversized-t-shirt-front.webp","alt":"Cursed Static oversized t-shirt in black, front view: fan-inspired Jujutsu Kaisen design by The Escape Door","side":"front","sample":true},{"src":"/mockups/cursed-static-oversized-t-shirt-back.webp","alt":"Cursed Static oversized t-shirt in black, back view: fan-inspired Jujutsu Kaisen design by The Escape Door","side":"back","sample":true}]'::jsonb, '[{"id":"p-cursed-static-oversized-t-shirt--oversized","label":"Oversized","price":800,"attrs":{"fit":"oversized"}}]'::jsonb, array['XS', 'S', 'M', 'L', 'XL', 'XXL']::text[], 800, false, null, true, true, true, 'made-to-order', '#C9B8FF', 0, true, '2026-10-19T00:00:00.000Z', '2026-10-19T00:00:00.000Z'),
  ('p-talisman-rain-t-shirt', 'talisman-rain-t-shirt', 'Talisman Rain T-Shirt', 'tshirt', 'jujutsu-kaisen', array['oversized', 'regular', 'baby-tee', 'apparel', 'jjk']::text[], 'Talisman Rain', '札の雨', 'Paper talisman strips falling through a screentone sky, drawn as an original ink panel. Pick your fit: oversized ₹800, regular ₹600 or baby tee ₹400 — same original print on a black tee. Sizes XS–XXL — ask us on WhatsApp for the size chart before you order.', '[{"src":"/mockups/talisman-rain-t-shirt-front.webp","alt":"Talisman Rain t-shirt in black, front view: fan-inspired Jujutsu Kaisen design by The Escape Door","side":"front","sample":true},{"src":"/mockups/talisman-rain-t-shirt-back.webp","alt":"Talisman Rain t-shirt in black, back view: fan-inspired Jujutsu Kaisen design by The Escape Door","side":"back","sample":true}]'::jsonb, '[{"id":"p-talisman-rain-t-shirt--oversized","label":"Oversized","price":800,"attrs":{"fit":"oversized"}},{"id":"p-talisman-rain-t-shirt--regular","label":"Regular","price":600,"attrs":{"fit":"regular"}},{"id":"p-talisman-rain-t-shirt--baby","label":"Baby tee","price":400,"attrs":{"fit":"baby"}}]'::jsonb, array['XS', 'S', 'M', 'L', 'XL', 'XXL']::text[], 400, false, null, true, false, false, 'made-to-order', '#A78BFF', 1, true, '2026-10-19T00:00:00.000Z', '2026-10-19T00:00:00.000Z'),
  ('p-violet-smoke-hoodie', 'violet-smoke-hoodie', 'Violet Smoke Hoodie', 'hoodie', 'jujutsu-kaisen', array['hoodie', 'gsm', 'apparel', 'jjk']::text[], 'Violet Smoke', '紫煙', 'Drifting cursed-energy smoke wraps the back of the hoodie in indigo and violet. Priced by fabric weight: 280–330 GSM ₹1200, 330–380 GSM ₹1500, 380–430 GSM ₹1800 and 430–600 GSM ₹2500. Higher GSM means a thicker, warmer hoodie. Sizes XS–XXL — ask us on WhatsApp for the size chart before you order.', '[{"src":"/mockups/violet-smoke-hoodie-front.webp","alt":"Violet Smoke hoodie in black, front view: fan-inspired Jujutsu Kaisen design by The Escape Door","side":"front","sample":true},{"src":"/mockups/violet-smoke-hoodie-back.webp","alt":"Violet Smoke hoodie in black, back view: fan-inspired Jujutsu Kaisen design by The Escape Door","side":"back","sample":true}]'::jsonb, '[{"id":"p-violet-smoke-hoodie--gsm-280-330","label":"LV.1 Everyday · 280–330 GSM","price":1200,"attrs":{"gsm":"280–330","level":"1"}},{"id":"p-violet-smoke-hoodie--gsm-330-380","label":"LV.2 Street · 330–380 GSM","price":1500,"attrs":{"gsm":"330–380","level":"2"}},{"id":"p-violet-smoke-hoodie--gsm-380-430","label":"LV.3 Heavyweight · 380–430 GSM","price":1800,"attrs":{"gsm":"380–430","level":"3"}},{"id":"p-violet-smoke-hoodie--gsm-430-600","label":"LV.4 Final Form · 430–600 GSM","price":2500,"attrs":{"gsm":"430–600","level":"4"}}]'::jsonb, array['XS', 'S', 'M', 'L', 'XL', 'XXL']::text[], 1200, false, null, true, false, false, 'made-to-order', '#4B2BFF', 2, true, '2026-10-19T00:00:00.000Z', '2026-10-19T00:00:00.000Z'),
  ('p-talisman-strip-polaroid-prints', 'talisman-strip-polaroid-prints', 'Talisman Strip Polaroid Prints', 'polaroid', 'jujutsu-kaisen', array['polaroid', 'collectible', 'jjk']::text[], 'Talisman Strip', '護符', 'Original talisman-and-smoke panels, framed polaroid style. Polaroid-style prints at ₹50 each — any 3 for ₹100, and you can mix designs and arcs to make the set. Custom prints from 20 pieces.', '[{"src":"/mockups/talisman-strip-polaroid-prints-front.webp","alt":"Talisman Strip polaroid-style prints laid out on a lavender panel: fan-inspired Jujutsu Kaisen design by The Escape Door","side":"front","sample":true}]'::jsonb, '[{"id":"p-talisman-strip-polaroid-prints--single","label":"Single print","price":50}]'::jsonb, null, 50, false, 'polaroid-3for100', true, true, false, 'in', '#C9B8FF', 3, true, '2026-10-19T00:00:00.000Z', '2026-10-19T00:00:00.000Z'),
  ('p-sealed-panel-poster', 'sealed-panel-poster', 'Sealed Panel Poster', 'poster', 'jujutsu-kaisen', array['poster', 'wall', 'jjk']::text[], 'Sealed Panel', '封印', 'A single manga panel bound shut with paper seals and speed lines. ₹200 each, or 6 for ₹1000 — buy 5, get 1 free, mixed designs allowed. Size and paper are confirmed with you on WhatsApp.', '[{"src":"/mockups/sealed-panel-poster-front.webp","alt":"Sealed Panel poster on a yellow panel: fan-inspired Jujutsu Kaisen design by The Escape Door","side":"front","sample":true}]'::jsonb, '[{"id":"p-sealed-panel-poster--single","label":"Poster","price":200}]'::jsonb, null, 200, false, 'poster-buy5get1', false, false, false, 'in', '#FFE14D', 4, true, '2026-10-19T00:00:00.000Z', '2026-10-19T00:00:00.000Z'),
  ('p-paper-talisman-bookmark', 'paper-talisman-bookmark', 'Paper Talisman Bookmark', 'bookmark', 'jujutsu-kaisen', array['bookmark', 'collectible', 'jjk']::text[], 'Paper Talisman', 'お札', 'Shaped like a paper talisman strip, inked in indigo. Plain ₹30 (4 for ₹100) or magnetic ₹100 (2 for ₹150) — the magnetic one folds over the page and snaps shut.', '[{"src":"/mockups/paper-talisman-bookmark-front.webp","alt":"Paper Talisman bookmark on a pink panel: fan-inspired Jujutsu Kaisen design by The Escape Door","side":"front","sample":true}]'::jsonb, '[{"id":"p-paper-talisman-bookmark--plain","label":"Plain","price":30,"attrs":{"kind":"plain"}},{"id":"p-paper-talisman-bookmark--magnetic","label":"Magnetic","price":100,"attrs":{"kind":"magnetic"}}]'::jsonb, null, 30, false, 'bookmark-plain-4for100', true, false, false, 'in', '#FFB8DE', 5, true, '2026-10-19T00:00:00.000Z', '2026-10-19T00:00:00.000Z'),
  ('p-static-eye-badge', 'static-eye-badge', 'Static Eye Badge', 'badge', 'jujutsu-kaisen', array['badge', 'collectible', 'jjk']::text[], 'Static Eye', null, 'A round badge of violet static and a single inked eye-glint. ₹50 each or 5 for ₹200 — mix any designs for a bag, jacket or lanyard.', '[{"src":"/mockups/static-eye-badge-front.webp","alt":"Static Eye pin badge on a lavender panel: fan-inspired Jujutsu Kaisen design by The Escape Door","side":"front","sample":true}]'::jsonb, '[{"id":"p-static-eye-badge--single","label":"Badge","price":50}]'::jsonb, null, 50, false, 'badge-5for200', true, false, false, 'in', '#C9B8FF', 6, true, '2026-10-19T00:00:00.000Z', '2026-10-19T00:00:00.000Z'),
  ('p-smoke-sigil-sticker', 'smoke-sigil-sticker', 'Smoke Sigil Sticker', 'sticker', 'jujutsu-kaisen', array['sticker', 'collectible', 'jjk']::text[], 'Smoke Sigil', null, 'An original smoke-curl sigil, die-cut. ₹30 for a single sticker. The ₹100 pack is also available — message us for how many stickers are in it this week.', '[{"src":"/mockups/smoke-sigil-sticker-front.webp","alt":"Smoke Sigil sticker on a violet panel: fan-inspired Jujutsu Kaisen design by The Escape Door","side":"front","sample":true}]'::jsonb, '[{"id":"p-smoke-sigil-sticker--single","label":"Single sticker","price":30,"attrs":{"pack":"single"}},{"id":"p-smoke-sigil-sticker--pack","label":"Sticker pack","price":100,"attrs":{"pack":"pack"}}]'::jsonb, null, 30, false, null, true, false, false, 'in', '#A78BFF', 7, true, '2026-10-19T00:00:00.000Z', '2026-10-19T00:00:00.000Z'),
  ('p-talisman-keychain', 'talisman-keychain', 'Talisman Keychain', 'keychain', 'jujutsu-kaisen', array['keychain', 'accessory', 'jjk']::text[], 'Talisman', null, 'A paper-talisman shaped keychain in indigo and paper white. ₹150 each.', '[{"src":"/mockups/talisman-keychain-front.webp","alt":"Talisman keychain on a lavender panel: fan-inspired Jujutsu Kaisen design by The Escape Door","side":"front","sample":true}]'::jsonb, '[{"id":"p-talisman-keychain--single","label":"Keychain","price":150}]'::jsonb, null, 150, false, null, false, false, false, 'in', '#C9B8FF', 8, true, '2026-10-19T00:00:00.000Z', '2026-10-19T00:00:00.000Z'),
  ('p-talisman-drop-earrings', 'talisman-drop-earrings', 'Talisman Drop Earrings', 'accessory', 'jujutsu-kaisen', array['earrings', 'accessory', 'jjk']::text[], 'Talisman Drop', null, 'Light drop earrings with a small talisman-strip charm. Earrings and accessories run ₹250–800 by piece; we confirm the exact price on WhatsApp.', '[{"src":"/mockups/talisman-drop-earrings-front.webp","alt":"Talisman Drop earrings on a pink panel: fan-inspired Jujutsu Kaisen design by The Escape Door","side":"front","sample":true}]'::jsonb, '[{"id":"p-talisman-drop-earrings--pair","label":"Pair","price":null,"attrs":{"range":"250–800"}}]'::jsonb, null, 250, false, null, false, false, false, 'in', '#FFB8DE', 9, true, '2026-10-19T00:00:00.000Z', '2026-10-19T00:00:00.000Z'),
  ('p-desk-guardian-figurine', 'desk-guardian-figurine', 'Desk Guardian Figurine', 'figurine', 'jujutsu-kaisen', array['figurine', 'collectible', 'jjk']::text[], 'Desk Guardian', null, 'Fan figurines for your desk or shelf. Standard figurines run ₹250–1200 by size; select premium pieces are ₹2500. Which figures are in stock changes often — ask on WhatsApp.', '[{"src":"/mockups/desk-guardian-figurine-front.webp","alt":"Desk Guardian figurine on a violet panel: fan-inspired Jujutsu Kaisen design by The Escape Door","side":"front","sample":true}]'::jsonb, '[{"id":"p-desk-guardian-figurine--standard","label":"Standard","price":null,"attrs":{"range":"250–1200"}},{"id":"p-desk-guardian-figurine--premium","label":"Premium","price":2500,"attrs":{"tier":"premium"}}]'::jsonb, null, 250, false, null, false, false, false, 'in', '#A78BFF', 10, true, '2026-10-19T00:00:00.000Z', '2026-10-19T00:00:00.000Z'),
  ('p-beyond-the-wall-oversized-t-shirt', 'beyond-the-wall-oversized-t-shirt', 'Beyond the Wall Oversized T-Shirt', 'tshirt', 'attack-on-titan', array['oversized', 'apparel', 'aot']::text[], 'Beyond the Wall', '壁の向こう', 'Three rings of wall drawn from above, with a red horizon cutting across the back. Printed on a black oversized drop-shoulder tee: back print up to 12×15 in, front hit up to 4×4 in. ₹800. Sizes XS–XXL — ask us on WhatsApp for the size chart before you order.', '[{"src":"/mockups/beyond-the-wall-oversized-t-shirt-front.webp","alt":"Beyond the Wall oversized t-shirt in black, front view: fan-inspired Attack on Titan design by The Escape Door","side":"front","sample":true},{"src":"/mockups/beyond-the-wall-oversized-t-shirt-back.webp","alt":"Beyond the Wall oversized t-shirt in black, back view: fan-inspired Attack on Titan design by The Escape Door","side":"back","sample":true}]'::jsonb, '[{"id":"p-beyond-the-wall-oversized-t-shirt--oversized","label":"Oversized","price":800,"attrs":{"fit":"oversized"}}]'::jsonb, array['XS', 'S', 'M', 'L', 'XL', 'XXL']::text[], 800, false, null, true, true, false, 'made-to-order', '#A39780', 11, true, '2026-10-19T00:00:00.000Z', '2026-10-19T00:00:00.000Z'),
  ('p-wind-torn-cloak-t-shirt', 'wind-torn-cloak-t-shirt', 'Wind-Torn Cloak T-Shirt', 'tshirt', 'attack-on-titan', array['oversized', 'regular', 'baby-tee', 'apparel', 'aot']::text[], 'Wind-Torn Cloak', '風の外套', 'Cloth ripping in a crosswind, inked in stone grey with one red stroke. Pick your fit: oversized ₹800, regular ₹600 or baby tee ₹400 — same original print on a black tee. Sizes XS–XXL — ask us on WhatsApp for the size chart before you order.', '[{"src":"/mockups/wind-torn-cloak-t-shirt-front.webp","alt":"Wind-Torn Cloak t-shirt in black, front view: fan-inspired Attack on Titan design by The Escape Door","side":"front","sample":true},{"src":"/mockups/wind-torn-cloak-t-shirt-back.webp","alt":"Wind-Torn Cloak t-shirt in black, back view: fan-inspired Attack on Titan design by The Escape Door","side":"back","sample":true}]'::jsonb, '[{"id":"p-wind-torn-cloak-t-shirt--oversized","label":"Oversized","price":800,"attrs":{"fit":"oversized"}},{"id":"p-wind-torn-cloak-t-shirt--regular","label":"Regular","price":600,"attrs":{"fit":"regular"}},{"id":"p-wind-torn-cloak-t-shirt--baby","label":"Baby tee","price":400,"attrs":{"fit":"baby"}}]'::jsonb, array['XS', 'S', 'M', 'L', 'XL', 'XXL']::text[], 400, false, null, true, false, false, 'made-to-order', '#FFE14D', 12, true, '2026-10-19T00:00:00.000Z', '2026-10-19T00:00:00.000Z'),
  ('p-stone-rampart-hoodie', 'stone-rampart-hoodie', 'Stone Rampart Hoodie', 'hoodie', 'attack-on-titan', array['hoodie', 'gsm', 'apparel', 'aot']::text[], 'Stone Rampart', '城壁', 'A wall of stacked stone blocks rising up the back, shaded in screentone. Priced by fabric weight: 280–330 GSM ₹1200, 330–380 GSM ₹1500, 380–430 GSM ₹1800 and 430–600 GSM ₹2500. Higher GSM means a thicker, warmer hoodie. Sizes XS–XXL — ask us on WhatsApp for the size chart before you order.', '[{"src":"/mockups/stone-rampart-hoodie-front.webp","alt":"Stone Rampart hoodie in black, front view: fan-inspired Attack on Titan design by The Escape Door","side":"front","sample":true},{"src":"/mockups/stone-rampart-hoodie-back.webp","alt":"Stone Rampart hoodie in black, back view: fan-inspired Attack on Titan design by The Escape Door","side":"back","sample":true}]'::jsonb, '[{"id":"p-stone-rampart-hoodie--gsm-280-330","label":"LV.1 Everyday · 280–330 GSM","price":1200,"attrs":{"gsm":"280–330","level":"1"}},{"id":"p-stone-rampart-hoodie--gsm-330-380","label":"LV.2 Street · 330–380 GSM","price":1500,"attrs":{"gsm":"330–380","level":"2"}},{"id":"p-stone-rampart-hoodie--gsm-380-430","label":"LV.3 Heavyweight · 380–430 GSM","price":1800,"attrs":{"gsm":"380–430","level":"3"}},{"id":"p-stone-rampart-hoodie--gsm-430-600","label":"LV.4 Final Form · 430–600 GSM","price":2500,"attrs":{"gsm":"430–600","level":"4"}}]'::jsonb, array['XS', 'S', 'M', 'L', 'XL', 'XXL']::text[], 1200, false, null, true, false, false, 'made-to-order', '#A39780', 13, true, '2026-10-19T00:00:00.000Z', '2026-10-19T00:00:00.000Z'),
  ('p-wall-line-polaroid-prints', 'wall-line-polaroid-prints', 'Wall Line Polaroid Prints', 'polaroid', 'attack-on-titan', array['polaroid', 'collectible', 'aot']::text[], 'Wall Line', '壁', 'Original wall-and-sky panels in grey and red, framed polaroid style. Polaroid-style prints at ₹50 each — any 3 for ₹100, and you can mix designs and arcs to make the set. Custom prints from 20 pieces.', '[{"src":"/mockups/wall-line-polaroid-prints-front.webp","alt":"Wall Line polaroid-style prints laid out on a lavender panel: fan-inspired Attack on Titan design by The Escape Door","side":"front","sample":true}]'::jsonb, '[{"id":"p-wall-line-polaroid-prints--single","label":"Single print","price":50}]'::jsonb, null, 50, false, 'polaroid-3for100', true, false, false, 'in', '#C9B8FF', 14, true, '2026-10-19T00:00:00.000Z', '2026-10-19T00:00:00.000Z'),
  ('p-red-horizon-poster', 'red-horizon-poster', 'Red Horizon Poster', 'poster', 'attack-on-titan', array['poster', 'wall', 'aot']::text[], 'Red Horizon', '赤い地平', 'A red sky over a ring of wall, drawn as a full-bleed manga splash page. ₹200 each, or 6 for ₹1000 — buy 5, get 1 free, mixed designs allowed. Size and paper are confirmed with you on WhatsApp.', '[{"src":"/mockups/red-horizon-poster-front.webp","alt":"Red Horizon poster on a red panel: fan-inspired Attack on Titan design by The Escape Door","side":"front","sample":true}]'::jsonb, '[{"id":"p-red-horizon-poster--single","label":"Poster","price":200}]'::jsonb, null, 200, false, 'poster-buy5get1', false, false, false, 'in', '#C8102E', 15, true, '2026-10-19T00:00:00.000Z', '2026-10-19T00:00:00.000Z'),
  ('p-cloth-and-wind-bookmark', 'cloth-and-wind-bookmark', 'Cloth and Wind Bookmark', 'bookmark', 'attack-on-titan', array['bookmark', 'collectible', 'aot']::text[], 'Cloth and Wind', null, 'A ribbon of wind-torn cloth running the length of the bookmark. Plain ₹30 (4 for ₹100) or magnetic ₹100 (2 for ₹150) — the magnetic one folds over the page and snaps shut.', '[{"src":"/mockups/cloth-and-wind-bookmark-front.webp","alt":"Cloth and Wind bookmark on a pink panel: fan-inspired Attack on Titan design by The Escape Door","side":"front","sample":true}]'::jsonb, '[{"id":"p-cloth-and-wind-bookmark--plain","label":"Plain","price":30,"attrs":{"kind":"plain"}},{"id":"p-cloth-and-wind-bookmark--magnetic","label":"Magnetic","price":100,"attrs":{"kind":"magnetic"}}]'::jsonb, null, 30, false, 'bookmark-plain-4for100', true, false, false, 'in', '#FFB8DE', 16, true, '2026-10-19T00:00:00.000Z', '2026-10-19T00:00:00.000Z'),
  ('p-rampart-ring-badge', 'rampart-ring-badge', 'Rampart Ring Badge', 'badge', 'attack-on-titan', array['badge', 'collectible', 'aot']::text[], 'Rampart Ring', null, 'Concentric wall rings on a stone-grey badge. ₹50 each or 5 for ₹200 — mix any designs for a bag, jacket or lanyard.', '[{"src":"/mockups/rampart-ring-badge-front.webp","alt":"Rampart Ring pin badge on a yellow panel: fan-inspired Attack on Titan design by The Escape Door","side":"front","sample":true}]'::jsonb, '[{"id":"p-rampart-ring-badge--single","label":"Badge","price":50}]'::jsonb, null, 50, false, 'badge-5for200', true, false, false, 'in', '#FFE14D', 17, true, '2026-10-19T00:00:00.000Z', '2026-10-19T00:00:00.000Z'),
