  ('p-wall-runner-cape', 'wall-runner-cape', 'Wall Runner Cape', 'cape', 'attack-on-titan', array['cape', 'cosplay', 'aot']::text[], 'Wall Runner', null, 'A long field cape for your cosplay, cut to move when you do. Capes run ₹700–1000 depending on length and fabric; we confirm the exact piece and price on WhatsApp.', '[{"src":"/mockups/wall-runner-cape-front.webp","alt":"Wall Runner cosplay cape on a stone grey panel: fan-inspired Attack on Titan design by The Escape Door","side":"front","sample":true}]'::jsonb, '[{"id":"p-wall-runner-cape--cape","label":"Cape","price":null,"attrs":{"range":"700–1000"}}]'::jsonb, null, 700, false, null, false, false, false, 'in', '#A39780', 19, true, '2026-10-19T00:00:00.000Z', '2026-10-19T00:00:00.000Z'),
  ('p-flame-breath-ribbon-oversized-t-shirt', 'flame-breath-ribbon-oversized-t-shirt', 'Flame Breath Ribbon Oversized T-Shirt', 'tshirt', 'demon-slayer', array['oversized', 'apparel', 'demon-slayer']::text[], 'Flame Breath Ribbon', '炎のリボン', 'A ribbon of brush-stroke flame curling across the back, edged in ink. Printed on a black oversized drop-shoulder tee: back print up to 12×15 in, front hit up to 4×4 in. ₹800. Sizes XS–XXL — ask us on WhatsApp for the size chart before you order.', '[{"src":"/mockups/flame-breath-ribbon-oversized-t-shirt-front.webp","alt":"Flame Breath Ribbon oversized t-shirt in black, front view: fan-inspired Demon Slayer design by The Escape Door","side":"front","sample":true},{"src":"/mockups/flame-breath-ribbon-oversized-t-shirt-back.webp","alt":"Flame Breath Ribbon oversized t-shirt in black, back view: fan-inspired Demon Slayer design by The Escape Door","side":"back","sample":true}]'::jsonb, '[{"id":"p-flame-breath-ribbon-oversized-t-shirt--oversized","label":"Oversized","price":800,"attrs":{"fit":"oversized"}}]'::jsonb, array['XS', 'S', 'M', 'L', 'XL', 'XXL']::text[], 800, false, null, true, true, false, 'made-to-order', '#FF6A13', 20, true, '2026-10-19T00:00:00.000Z', '2026-10-19T00:00:00.000Z'),
