  ('p-reading-room-tote-bag', 'reading-room-tote-bag', 'Reading Room Tote Bag', 'tote', 'beyond-anime', array['tote', 'bookish']::text[], 'Reading Room', null, 'A canvas tote for books, sketchbooks and fest hauls. Price on request — message us on WhatsApp and we will quote it.', '[{"src":"/mockups/reading-room-tote-bag-front.webp","alt":"Reading Room tote bag on a colour panel: bookish design by The Escape Door","side":"front","sample":true}]'::jsonb, '[{"id":"p-reading-room-tote-bag--standard","label":"Standard","price":null}]'::jsonb, null, null, true, null, false, false, false, 'made-to-order', '#F4EFE6', 63, true, '2026-10-19T00:00:00.000Z', '2026-10-19T00:00:00.000Z'),
  ('p-margin-notes-stationery-set', 'margin-notes-stationery-set', 'Margin Notes Stationery Set', 'stationery', 'beyond-anime', array['stationery', 'bookish']::text[], 'Margin Notes', null, 'Fandom stationery — notebooks and paper goods; the set changes with each batch. Price on request — message us on WhatsApp and we will quote it.', '[{"src":"/mockups/margin-notes-stationery-set-front.webp","alt":"Margin Notes stationery set on a lavender panel: bookish design by The Escape Door","side":"front","sample":true}]'::jsonb, '[{"id":"p-margin-notes-stationery-set--standard","label":"Standard","price":null}]'::jsonb, null, null, true, null, false, false, false, 'made-to-order', '#C9B8FF', 64, true, '2026-10-19T00:00:00.000Z', '2026-10-19T00:00:00.000Z')
