insert into public.settings (key, value) values
  ('site', '{"heroKicker":"Original anime merch · India","heroTitle":"Anime merch, drawn like a living manga volume","heroSub":"Oversized tees, hoodies, polaroids, posters and props — original fan-inspired designs at student prices, custom-made on demand. Pick your arc.","bannerText":"3 polaroids ₹100 · 6 posters ₹1000 · custom orders open","tickerWords":["YOU ARE MY SPECIAL","PICK YOUR ARC","ドン","CUSTOM MADE","OVERSIZED ₹800","3 POLAROIDS ₹100","新作","FANDOM PARTNER"],"whatsapp":"","instagram":"https://www.instagram.com/escapedoor.in"}'::jsonb),
  ('hoodie_tiers', '[{"id":"gsm-280-330","level":1,"code":"LV.1","name":"Everyday","gsmMin":280,"gsmMax":330,"gsmLabel":"280–330 GSM","price":1200,"feel":"The lightest tier. Easy over a tee for lectures, travel and air-conditioned rooms."},{"id":"gsm-330-380","level":2,"code":"LV.2","name":"Street","gsmMin":330,"gsmMax":380,"gsmLabel":"330–380 GSM","price":1500,"feel":"Midweight. More body and structure, still easy to layer."},{"id":"gsm-380-430","level":3,"code":"LV.3","name":"Heavyweight","gsmMin":380,"gsmMax":430,"gsmLabel":"380–430 GSM","price":1800,"feel":"Dense fabric that holds its shape. Built for cold evenings."},{"id":"gsm-430-600","level":4,"code":"LV.4","name":"Final Form","gsmMin":430,"gsmMax":600,"gsmLabel":"430–600 GSM","price":2500,"feel":"The heaviest tier we make. Thick, warm and stiff in the drape."}]'::jsonb),
  ('tee_fits', '[{"id":"oversized","label":"Oversized","price":800,"blurb":"Drop shoulder, boxy body. The fit our back prints are drawn for."},{"id":"regular","label":"Regular","price":600,"blurb":"Classic everyday fit."},{"id":"baby","label":"Baby tee","price":400,"blurb":"Short, fitted silhouette."}]'::jsonb),
  ('apparel_custom', '{"companyDesignFee":200,"halfHalfFee":200,"zones":{"front":{"w":4,"h":4,"unit":"in"},"back":{"w":12,"h":15,"unit":"in"}},"note":"\"Depends on cloth price.\" Whether the ₹200 design fee is per piece or per order is to be confirmed — quotes treat it as once per order and are confirmed on WhatsApp."}'::jsonb)
